def max_subarray_product(arr):
    assert isinstance(arr, list) and len(arr) > 0 and all(isinstance(x, (int, float)) for x in arr)
    cur_max = cur_min = global_max = arr[0]
    for x in arr[1:]:
        if x == 0:
            cur_max = cur_min = 0
        else:
            candidates = (x, cur_max * x, cur_min * x)
            cur_max, cur_min = max(candidates), min(candidates)
        global_max = max(global_max, cur_max)
    return global_max
